// Firebase layer: sign-in (Google, email/password), the `release` Cloud Function, live leaderboards and the
// campaign (one studio read per load, the campaign* callables, film history on demand, the campaign board).
// Exposes window.GLNet and fires "glnet-ready" (or "glnet-off" when Firebase isn't configured or can't load;
// the game then runs offline and keeps results on the device).
// Config comes from firebase-config.js (generated by tools/firebase_setup.mjs from .env; the web config is
// public by design). It talks to the real project; add ?emu on localhost to use the Firebase emulators.
const SDK = "https://www.gstatic.com/firebasejs/10.14.1/";

function off(why) {
  window.GLNet = null;
  window.dispatchEvent(new CustomEvent("glnet-off", { detail: why }));
}

async function start() {
  const cfg = window.FIREBASE_CONFIG;
  if (!cfg || !cfg.apiKey || !cfg.projectId) return off("no-config");
  const [{ initializeApp }, Au, Fs, Fn] = await Promise.all([
    import(SDK + "firebase-app.js"), import(SDK + "firebase-auth.js"),
    import(SDK + "firebase-firestore.js"), import(SDK + "firebase-functions.js"),
  ]);
  const app = initializeApp(cfg);
  const auth = Au.getAuth(app), db = Fs.getFirestore(app), fns = Fn.getFunctions(app);
  // The real project by default; the local emulators only when asked for with ?emu (or useEmulators in the config).
  const local = ["localhost", "127.0.0.1"].includes(location.hostname);
  const emu = cfg.useEmulators ?? (local && new URLSearchParams(location.search).has("emu"));
  if (emu) {
    Au.connectAuthEmulator(auth, "http://127.0.0.1:9099", { disableWarnings: true });
    Fs.connectFirestoreEmulator(db, "127.0.0.1", 8080);
    Fn.connectFunctionsEmulator(fns, "127.0.0.1", 5001);
  }
  const callRelease = Fn.httpsCallable(fns, "release");
  const listeners = new Set();
  const shape = (u) => u && { uid: u.uid, name: u.displayName || (u.email ? u.email.split("@")[0] : "Studio"), email: u.email, photo: u.photoURL, verified: u.emailVerified };

  const net = {
    emulators: emu,
    user: null,
    onUser(cb) { listeners.add(cb); cb(net.user); return () => listeners.delete(cb); },
    google() { return Au.signInWithPopup(auth, new Au.GoogleAuthProvider()); },
    emailIn(email, pw) { return Au.signInWithEmailAndPassword(auth, email, pw); },
    async emailUp(name, email, pw) {
      const c = await Au.createUserWithEmailAndPassword(auth, email, pw);
      await Au.updateProfile(c.user, { displayName: name });
      await c.user.getIdToken(true); // so the server sees the studio name straight away
      Au.sendEmailVerification(c.user).catch(() => {});
      net.user = shape(auth.currentUser);
      listeners.forEach((cb) => cb(net.user));
      return c;
    },
    reset(email) { return Au.sendPasswordResetEmail(auth, email); },
    signOut() { return Au.signOut(auth); },
    async release(payload) { return (await callRelease(payload)).data; },
    // Campaign: the player's studio (null if they haven't founded one). One read; every write is a callable
    // (campaignStart, campaignProject, campaignRelease, campaignPass, campaignRename) that returns the new studio.
    async campaignLoad() {
      if (!net.user) return null;
      const s = await Fs.getDoc(Fs.doc(db, "campaigns", net.user.uid));
      return s.exists() ? s.data() : null;
    },
    async campaign(name, payload) { return (await Fn.httpsCallable(fns, name)(payload || {})).data; },
    // Every released film of the studio, newest first (only for the history screen).
    async campaignFilms() {
      if (!net.user) return [];
      const q = Fs.query(Fs.collection(db, "campaigns", net.user.uid, "films"), Fs.orderBy("projectIndex", "desc"), Fs.limit(200));
      return (await Fs.getDocs(q)).docs.map((d) => d.data());
    },
    // Campaign board: fewest films to reach the A-list, then fewer bailouts, then higher lifetime profit.
    watchCampaignBoard(cb, err) {
      const q = Fs.query(Fs.collection(db, "campaignBoard"), Fs.orderBy("filmsToATier", "asc"), Fs.orderBy("bailouts", "asc"), Fs.orderBy("lifetimeProfit", "desc"), Fs.limit(25));
      return Fs.onSnapshot(q, { includeMetadataChanges: true }, (s) => cb(s.docs.map((d) => Object.assign({ uid: d.id }, d.data())), s.metadata.fromCache), err);
    },
    // Top of one day's board, live.
    watchBoard(boardId, cb, err) {
      const q = Fs.query(Fs.collection(db, "boards", boardId, "entries"), Fs.orderBy("profit", "desc"), Fs.limit(25));
      // fromCache with no rows means the server hasn't answered yet (offline or still connecting).
      return Fs.onSnapshot(q, { includeMetadataChanges: true }, (s) => cb(s.docs.map((d) => d.data()), s.metadata.fromCache), err);
    },
    // The signed-in player's own best runs (their progression), newest days first.
    watchRuns(cb, err) {
      if (!net.user) return () => {};
      const q = Fs.query(Fs.collection(db, "users", net.user.uid, "runs"), Fs.orderBy("day", "desc"), Fs.limit(400));
      return Fs.onSnapshot(q, (s) => cb(s.docs.map((d) => Object.assign({ id: d.id }, d.data()))), err);
    },
    errorText(e) {
      const code = (e && e.code) || "";
      const msg = {
        "auth/invalid-credential": "That email and password don't match.",
        "auth/wrong-password": "That email and password don't match.",
        "auth/user-not-found": "There's no account with that email.",
        "auth/email-already-in-use": "There's already an account with that email. Sign in instead.",
        "auth/weak-password": "Use a password of at least 6 characters.",
        "auth/invalid-email": "That email address doesn't look right.",
        "auth/popup-closed-by-user": "Sign-in was cancelled.",
        "auth/cancelled-popup-request": "Sign-in was cancelled.",
        "auth/popup-blocked": "Your browser blocked the sign-in window. Allow pop-ups for this site and try again.",
        "auth/operation-not-allowed": "That sign-in method isn't turned on for this game yet.",
        "auth/unauthorized-domain": "Sign-in isn't allowed from this web address yet (add it under Authentication → Settings → Authorized domains).",
        "auth/too-many-requests": "Too many attempts. Wait a minute and try again.",
        "auth/network-request-failed": "Can't reach the sign-in service. Check your connection.",
        "functions/unauthenticated": "Sign in to post to the leaderboard.",
        "functions/deadline-exceeded": "The server took too long. Try again.",
        "functions/unavailable": "The leaderboard server can't be reached right now.",
        "functions/internal": "The leaderboard server hit an error.",
        "permission-denied": "The leaderboard can't be read right now.",
        "unavailable": "The leaderboard can't be reached right now.",
      }[code];
      if (msg) return msg;
      if (code.startsWith("functions/") && e.message) return e.message; // the server's own explanation
      return "Something went wrong. Try again.";
    },
  };
  Au.onAuthStateChanged(auth, (u) => { net.user = shape(u); listeners.forEach((cb) => cb(net.user)); });
  window.GLNet = net;
  window.dispatchEvent(new Event("glnet-ready"));
}

start().catch((e) => { console.warn("GREENLIGHT: online features unavailable", e); off("load-failed"); });
